#!/usr/bin/env python3
"""Golden fixtures of the CLI behaviour and of generated bytes (PLAN3 D23, D30).

Stdlib only, Python >= 3.9. Scaffolding of the migration, not a CI step: it proves "as before" by comparison
while code moves between modules.

Commands:
  list                           case and generator ids
  check [--only ID,...]          exit 0 match, 1 mismatch (unified diff per case), 2 usage or environment
  capture [--only ID,...] --reason TEXT
                                 rewrite fixtures; every case runs twice and an unstable one refuses the capture;
                                 records captured_from (git short sha) and reason in cases.json and generation.json

Cases (tests/golden/cases.json) run in one sandbox of scripts/dev-sandbox.sh (the real HOME is not touched, the
sandbox is removed in ``finally``), cwd is the repository root. Only commands that change nothing are allowed:
the tracked and untracked state (``git status --porcelain``) must be the same after the run.
Generation (tests/golden/generation.json): sha256 of the tracked files that generators write (``outputs`` globs)
plus the exit code of each generator's ``check_argv``.
"""
from __future__ import annotations

import argparse
import difflib
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
from contextlib import contextmanager
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
GOLDEN_DIR = "tests/golden"
CASES_FILE = f"{GOLDEN_DIR}/cases.json"
GENERATION_FILE = f"{GOLDEN_DIR}/generation.json"
CLI_DIR = f"{GOLDEN_DIR}/cli"
SANDBOX_SCRIPT = "scripts/dev-sandbox.sh"
SCHEMA_CASES = "golden-cases/v1"
SCHEMA_GENERATION = "golden-generation/v1"
DEFAULT_TIMEOUT_S = 120
GENERATOR_TIMEOUT_S = 900
FIXTURE_PARTS = ("exit: ", "--- stdout ---", "--- stderr ---")


class GoldenError(Exception):
    """Environment or usage problem (exit 2)."""


# ---------------------------------------------------------------- normalization

def build_context(root: Path, sandbox: str = "", home: str = "") -> dict:
    return {"repo": str(root), "sandbox": sandbox, "home": home or os.path.expanduser("~")}


def _variants(path: str) -> list:
    """The path as given and its resolved form, longest first, without empties and duplicates."""
    out = []
    for item in (path, os.path.realpath(path) if path else ""):
        if item and item not in out:
            out.append(item)
    return sorted(out, key=len, reverse=True)


def normalize(text: str, rules: list, context: dict) -> str:
    """Apply the rules in order. A rule is {type: repo|sandbox|home, token} or {type: regex, pattern, replace}."""
    for rule in rules:
        kind = rule["type"]
        if kind in ("repo", "sandbox", "home"):
            for value in _variants(context.get(kind, "")):
                text = text.replace(value, rule["token"])
        elif kind == "regex":
            text = re.sub(rule["pattern"], rule["replace"], text)
        else:
            raise GoldenError(f"unknown normalization rule type: {kind}")
    return text


def validate_rules(rules: list) -> None:
    for rule in rules:
        if not rule.get("reason"):
            raise GoldenError(f"normalization rule {rule.get('name', rule)} has no reason")


def render_fixture(rc: int, stdout: str, stderr: str) -> str:
    return f"exit: {rc}\n--- stdout ---\n{stdout}\n--- stderr ---\n{stderr}\n"


def expand(value: str, context: dict) -> str:
    return value.replace("{REPO}", context["repo"]).replace("{SANDBOX}", context["sandbox"])


# ---------------------------------------------------------------- runners

class SandboxRunner:
    """Runs commands through ``dev-sandbox.sh run``; the tests replace it with a fake exposing ``run``."""

    def __init__(self, root: Path, directory: str):
        self.root = root
        self.directory = directory

    def run(self, argv, stdin=None, timeout=DEFAULT_TIMEOUT_S, cwd=None, env=None):
        command = [str(self.root / SANDBOX_SCRIPT), "run", self.directory, "--"]
        if env:
            command += ["env"] + [f"{k}={v}" for k, v in sorted(env.items())]
        command += list(argv)
        try:
            proc = subprocess.run(command, input=stdin, capture_output=True, text=True, timeout=timeout,
                                  cwd=str(cwd or self.root))
        except subprocess.TimeoutExpired:
            return 124, "", f"golden: timeout after {timeout}s"
        return proc.returncode, proc.stdout, proc.stderr


@contextmanager
def sandbox(root: Path, setup: list):
    script = str(root / SANDBOX_SCRIPT)
    proc = subprocess.run([script, "new", "--name", f"golden-{os.getpid()}"], capture_output=True, text=True)
    if proc.returncode != 0:
        raise GoldenError(f"sandbox: {proc.stderr.strip() or proc.stdout.strip()}")
    directory = proc.stdout.strip().splitlines()[-1]
    try:
        for item in setup:
            src, dst = root / item["from"], Path(directory) / item["to"]
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copytree(src, dst)
        yield SandboxRunner(root, directory), directory
    finally:
        subprocess.run([script, "remove", directory], capture_output=True, text=True)


def repo_state(root: Path) -> str:
    proc = subprocess.run(["git", "status", "--porcelain", "-z", "--untracked-files=all"], cwd=str(root),
                          capture_output=True, text=True)
    if proc.returncode != 0:
        raise GoldenError(f"git status: {proc.stderr.strip()}")
    return proc.stdout


def head_sha(root: Path) -> str:
    proc = subprocess.run(["git", "rev-parse", "--short=12", "HEAD"], cwd=str(root), capture_output=True, text=True)
    if proc.returncode != 0:
        raise GoldenError(f"git rev-parse: {proc.stderr.strip()}")
    return proc.stdout.strip()


def tracked_files(root: Path) -> list:
    proc = subprocess.run(["git", "ls-files", "-z"], cwd=str(root), capture_output=True, text=True)
    if proc.returncode != 0:
        raise GoldenError(f"git ls-files: {proc.stderr.strip()}")
    return sorted(p for p in proc.stdout.split("\0") if p)


# ---------------------------------------------------------------- cases

def run_case(runner, case: dict, rules: list, context: dict) -> str:
    argv = [expand(a, context) for a in case["argv"]]
    stdin = case.get("stdin")
    cwd = Path(expand(case["cwd"], context)) if "cwd" in case else None
    rc, out, err = runner.run(argv, stdin=stdin, timeout=case.get("timeout_s", DEFAULT_TIMEOUT_S),
                              cwd=cwd, env={"PYTHONDONTWRITEBYTECODE": "1"})
    return render_fixture(rc, normalize(out.rstrip("\n"), rules, context), normalize(err.rstrip("\n"), rules, context))


def fixture_path(root: Path, case_id: str) -> Path:
    return root / CLI_DIR / f"{case_id}.txt"


def check_cases(runner, cases_doc: dict, only, context: dict, root: Path) -> list:
    """Return mismatch descriptions (unified diffs)."""
    problems = []
    for case in cases_doc["cases"]:
        if only is not None and case["id"] not in only:
            continue
        path = fixture_path(root, case["id"])
        if not path.is_file():
            problems.append(f"{case['id']}: fixture {path.relative_to(root)} is missing")
            continue
        expected = path.read_text(encoding="utf-8")
        actual = run_case(runner, case, cases_doc["normalize"], context)
        if actual != expected:
            diff = "".join(difflib.unified_diff(expected.splitlines(True), actual.splitlines(True),
                                                f"{case['id']} (golden)", f"{case['id']} (now)"))
            problems.append(f"{case['id']}: output differs\n{diff}")
    return problems


def capture_cases(runner, cases_doc: dict, only, context: dict, root: Path) -> list:
    """Run each case twice; write the fixtures of stable cases. Return ids that were unstable."""
    unstable, results = [], {}
    for case in cases_doc["cases"]:
        if only is not None and case["id"] not in only:
            continue
        first = run_case(runner, case, cases_doc["normalize"], context)
        second = run_case(runner, case, cases_doc["normalize"], context)
        if first != second:
            unstable.append(case["id"])
        else:
            results[case["id"]] = first
    if unstable:
        return unstable
    for case_id, text in results.items():
        path = fixture_path(root, case_id)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
    return []


# ---------------------------------------------------------------- generation

def glob_regex(pattern: str):
    """``**/`` crosses directories (also none), ``*`` and ``?`` stay inside one path segment."""
    out, i = "", 0
    while i < len(pattern):
        if pattern.startswith("**/", i):
            out += "(?:.*/)?"
            i += 3
        elif pattern.startswith("**", i):
            out += ".*"
            i += 2
        elif pattern[i] == "*":
            out += "[^/]*"
            i += 1
        elif pattern[i] == "?":
            out += "[^/]"
            i += 1
        else:
            out += re.escape(pattern[i])
            i += 1
    return re.compile(out + r"\Z")


def output_files(generators: list, tracked: list) -> dict:
    """{generator id: sorted tracked files matching its outputs}."""
    found = {}
    for gen in generators:
        regexes = [glob_regex(g) for g in gen.get("outputs", [])]
        found[gen["id"]] = [p for p in tracked if any(r.match(p) for r in regexes)]
    return found


def sha256_file(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def compute_digests(root: Path, generators: list, tracked: list) -> dict:
    digests = {}
    for files in output_files(generators, tracked).values():
        for rel in files:
            if (root / rel).is_file():
                digests[rel] = sha256_file(root / rel)
    return dict(sorted(digests.items()))


def check_digests(root: Path, generation: dict, tracked: list, only) -> list:
    generators = [g for g in generation["generators"] if only is None or g["id"] in only]
    scope = {rel for files in output_files(generators, tracked).values() for rel in files}
    scope |= {rel for rel in generation["digests"] if any(glob_regex(o).match(rel)
                                                          for g in generators for o in g.get("outputs", []))}
    problems = []
    for rel in sorted(scope):
        recorded = generation["digests"].get(rel)
        path = root / rel
        if recorded is None:
            problems.append(f"{rel}: tracked generated file is not in digests")
        elif not path.is_file():
            problems.append(f"{rel}: generated file disappeared")
        elif sha256_file(path) != recorded:
            problems.append(f"{rel}: sha256 differs from digests")
    return problems


def run_generators(runner, generators: list, only, context: dict) -> list:
    problems = []
    for gen in generators:
        if only is not None and gen["id"] not in only:
            continue
        env = {k: expand(v, context) for k, v in gen.get("env", {}).items()}
        env["PYTHONDONTWRITEBYTECODE"] = "1"
        cwd = Path(context["repo"]) / gen.get("cwd", ".")
        argv = [expand(a, context) for a in gen["check_argv"]]
        rc, out, err = runner.run(argv, timeout=gen.get("timeout_s", GENERATOR_TIMEOUT_S), cwd=cwd, env=env)
        if rc != 0:
            tail = "\n".join((err or out).strip().splitlines()[-15:])
            problems.append(f"{gen['id']}: check exited {rc}\n{tail}")
    return problems


# ---------------------------------------------------------------- commands

def load(root: Path):
    try:
        cases = json.loads((root / CASES_FILE).read_text(encoding="utf-8"))
        generation = json.loads((root / GENERATION_FILE).read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise GoldenError(f"cannot read golden files: {exc}")
    validate_rules(cases["normalize"])
    return cases, generation


def parse_only(value):
    return None if not value else {x for x in value.split(",") if x}


def write_json(path: Path, data: dict) -> None:
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def cmd_list(root: Path, args) -> int:
    cases, generation = load(root)
    for case in cases["cases"]:
        print(f"case\t{case['id']}")
    for gen in generation["generators"]:
        print(f"generator\t{gen['id']}")
    return 0


def known_ids(cases: dict, generation: dict) -> set:
    return {c["id"] for c in cases["cases"]} | {g["id"] for g in generation["generators"]}


def cmd_check(root: Path, args, runner_factory=sandbox) -> int:
    cases, generation = load(root)
    only = parse_only(args.only)
    unknown = (only or set()) - known_ids(cases, generation)
    if unknown:
        raise GoldenError(f"unknown ids: {', '.join(sorted(unknown))}")
    before = repo_state(root)
    problems = []
    with runner_factory(root, cases.get("setup", [])) as (runner, directory):
        context = build_context(root, directory)
        problems += check_cases(runner, cases, only, context, root)
        problems += check_digests(root, generation, tracked_files(root), only)
        problems += run_generators(runner, generation["generators"], only, context)
    if repo_state(root) != before:
        raise GoldenError("a case changed the repository state (git status differs after the run)")
    for problem in problems:
        print(problem, file=sys.stderr)
    return 1 if problems else 0


def cmd_capture(root: Path, args, runner_factory=sandbox) -> int:
    if not args.reason or not args.reason.strip():
        raise GoldenError("capture needs --reason TEXT")
    cases, generation = load(root)
    only = parse_only(args.only)
    unknown = (only or set()) - known_ids(cases, generation)
    if unknown:
        raise GoldenError(f"unknown ids: {', '.join(sorted(unknown))}")
    before = repo_state(root)
    with runner_factory(root, cases.get("setup", [])) as (runner, directory):
        context = build_context(root, directory)
        unstable = capture_cases(runner, cases, only, context, root)
        if unstable:
            print("unstable between two runs, nothing written: " + ", ".join(unstable), file=sys.stderr)
            return 1
        problems = run_generators(runner, generation["generators"], only, context)
    if problems:
        for problem in problems:
            print(problem, file=sys.stderr)
        print("generator check failed, digests not captured", file=sys.stderr)
        return 1
    sha = head_sha(root)
    selected = [g for g in generation["generators"] if only is None or g["id"] in only]
    tracked = tracked_files(root)
    fresh = compute_digests(root, selected, tracked)
    stale = {rel for files in output_files(selected, tracked).values() for rel in files}
    generation["digests"] = dict(sorted({**{k: v for k, v in generation["digests"].items() if k not in stale},
                                         **fresh}.items()))
    for doc, path, schema in ((cases, CASES_FILE, SCHEMA_CASES), (generation, GENERATION_FILE, SCHEMA_GENERATION)):
        doc["schema"], doc["captured_from"], doc["reason"] = schema, sha, args.reason.strip()
        write_json(root / path, doc)
    # fixtures are the only expected changes: nothing outside tests/golden may move
    after = repo_state(root)
    if after != before:
        changed = [e[3:] for e in after.split("\0") if e and not e[3:].startswith(GOLDEN_DIR + "/")
                   and e not in before.split("\0")]
        if changed:
            raise GoldenError("a case changed files outside tests/golden: " + ", ".join(changed))
    print(f"captured at {sha}: {args.reason.strip()}")
    return 0


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(prog="golden.py", description=__doc__.split("\n\n")[0])
    sub = parser.add_subparsers(dest="command", required=True)
    sub.add_parser("list")
    check = sub.add_parser("check")
    check.add_argument("--only", default="")
    capture = sub.add_parser("capture")
    capture.add_argument("--only", default="")
    capture.add_argument("--reason", default="")
    args = parser.parse_args(argv)
    try:
        return {"list": cmd_list, "check": cmd_check, "capture": cmd_capture}[args.command](ROOT, args)
    except GoldenError as exc:
        print(f"GOLDEN: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main())
